using Clock=chrono::steady_clock;
static long long nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
static volatile sig_atomic_t reload_flag=0;
static void onhup(int){reload_flag=1;}
static string trim(string s){size_t a=s.find_first_not_of(" \t\r"),b=s.find_last_not_of(" \t\r");return a==string::npos?"":s.substr(a,b-a+1);}
static string lower(string s){for(char &c:s) if(c>='A'&&c<='Z') c+=32;return s;}
static bool number(const string&s,unsigned long long &n,bool positive=true){if(s.empty())return false;n=0;for(unsigned char c:s){if(c<'0'||c>'9'||n>(ULLONG_MAX-(c-'0'))/10)return false;n=n*10+c-'0';}return !positive||n>0;}
static bool address(const string&s,sockaddr_in &a){size_t p=s.rfind(':');if(p==string::npos)return false;string ip=s.substr(0,p),port=s.substr(p+1);unsigned long long n;if(!number(port,n)||n>65535)return false;memset(&a,0,sizeof a);a.sin_family=AF_INET;a.sin_port=htons(n);return inet_pton(AF_INET,ip.c_str(),&a.sin_addr)==1;}
struct Config{string listen,root,origin,trusted; sockaddr_in bindaddr{},up{};in_addr trust{};int rootfd=-1;uint64_t maxconn,header,htime,idle,wtime,maxreq,depth,cb,gb,refill;};
static bool loadconfig(const string&path,Config &c){ifstream f(path);if(!f)return false;unordered_map<string,string> m;string l;while(getline(f,l)){l=trim(l);if(l.empty()||l[0]=='#')continue;auto p=l.find('=');if(p==string::npos)return false;string k=trim(l.substr(0,p)),v=trim(l.substr(p+1));if(k.empty()||v.empty()||m.count(k))return false;m[k]=v;}if(!f.eof())return false;const vector<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","client_burst","global_burst","refill_ms","trusted_peer"};if(m.size()!=keys.size())return false;for(auto &k:keys)if(!m.count(k))return false;c.listen=m["listen"];c.root=m["root"];c.origin=m["origin_address"];c.trusted=m["trusted_peer"];if(c.root.empty()||c.root[0]!='/'||!address(c.listen,c.bindaddr)||!address(c.origin,c.up)||inet_pton(AF_INET,c.trusted.c_str(),&c.trust)!=1)return false;auto get=[&](const char*k,uint64_t&v){unsigned long long x;if(!number(m[k],x))return false;v=x;return true;};if(!get("max_connections",c.maxconn)||!get("header_bytes",c.header)||!get("header_timeout_ms",c.htime)||!get("idle_timeout_ms",c.idle)||!get("write_timeout_ms",c.wtime)||!get("max_requests",c.maxreq)||!get("pipeline_depth",c.depth)||!get("client_burst",c.cb)||!get("global_burst",c.gb)||!get("refill_ms",c.refill))return false;struct stat st;if(stat(c.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;c.rootfd=open(c.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);return c.rootfd>=0;}
static int listener(const sockaddr_in&a){int fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0)return -1;int one=1;setsockopt(fd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof one);if(bind(fd,(sockaddr*)&a,sizeof a)||listen(fd,4096)){close(fd);return -1;}return fd;}
static bool tokenchar(unsigned char c){return (c>='0'&&c<='9')||(c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c!=0&&strchr("!#$%&'*+-.^_`|~",c));}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;unsigned n;uint32_t x;if(c>=0xc2&&c<=0xdf){n=1;x=c&31;}else if(c>=0xe0&&c<=0xef){n=2;x=c&15;}else if(c>=0xf0&&c<=0xf4){n=3;x=c&7;}else return false;if(i+n>s.size())return false;for(unsigned j=0;j<n;j++){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;x=(x<<6)|(d&63);}if((n==2&&x<0x800)||(n==3&&x<0x10000)||x>0x10ffff||(x>=0xd800&&x<=0xdfff))return false;}return true;}
static int unhex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool pathdecode(const string&t,string &p){if(t.empty()||t[0]!='/'||t.find('#')!=string::npos)return false;size_t end=t.find('?');if(end==string::npos)end=t.size();p.clear();for(size_t i=0;i<end;i++){unsigned char c=t[i];if(c=='%'){if(i+2>=end)return false;int a=unhex(t[i+1]),b=unhex(t[i+2]);if(a<0||b<0)return false;c=(a<<4)|b;i+=2;}if(!c||c=='\\'||c<32||c==127)return false;p.push_back(c);}return utf8(p);}
static bool traversal(const string&p){size_t i=0;while(i<p.size()){while(i<p.size()&&p[i]=='/')i++;size_t j=p.find('/',i);if(j==string::npos)j=p.size();if(p.substr(i,j-i)=="..")return true;i=j;}return false;}
static int fileopen(int root,const string&p,uint64_t&sz){if(p.empty())return -403;int dir=dup(root);if(dir<0)return -403;size_t i=0;while(i<p.size()){while(i<p.size()&&p[i]=='/')i++;if(i==p.size())break;size_t j=p.find('/',i);if(j==string::npos)j=p.size();string part=p.substr(i,j-i);if(part=="."){i=j;continue;}bool last=j==p.size();int fd=openat(dir,part.c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK|(last?0:O_DIRECTORY));if(fd<0){int e=errno;struct stat st;bool prohibited=fstatat(dir,part.c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&!S_ISREG(st.st_mode)&&!S_ISDIR(st.st_mode);close(dir);if(prohibited||e==ELOOP||e==EACCES||e==EPERM)return -403;return -404;}close(dir);dir=fd;if(last){struct stat st;if(fstat(fd,&st)||!S_ISREG(st.st_mode)){close(fd);return -403;}sz=st.st_size;return fd;}i=j;}close(dir);return -403;}
struct Bucket{double tokens;long long time;};
struct Conn{int fd=-1,ufd=-1,file=-1;uint64_t id=0,uid=0;uint32_t peer=0;string in,out,upout,upin;size_t sent=0,upsent=0;uint64_t filerem=0,uprem=0,count=0;bool active=false,closeafter=false,head=false,upheader=false,updone=false,upconnecting=false,upbuffer=false,rdhup=false;long long first=0,last=0,lastread=0,write=0,upactivity=0;};
struct Ref{Conn*c;bool upstream;};
static int ep=-1;static int lfd=-1;static uint64_t nextid=2;static unordered_map<uint64_t,unique_ptr<Conn>> clients;static unordered_map<uint64_t,Ref> refs;static Config cfg;static unordered_map<uint32_t,Bucket> buckets;static Bucket globalbucket;static string configpath;
static bool ctl(int op,int fd,uint32_t ev,uint64_t id){epoll_event e{};e.events=ev;e.data.u64=id;return epoll_ctl(ep,op,fd,&e)==0;}
static void closeup(Conn&c){if(c.ufd>=0){epoll_ctl(ep,EPOLL_CTL_DEL,c.ufd,nullptr);close(c.ufd);refs.erase(c.uid);c.ufd=-1;}}
static void destroy(uint64_t id){auto it=clients.find(id);if(it==clients.end())return;Conn&c=*it->second;closeup(c);if(c.file>=0)close(c.file);epoll_ctl(ep,EPOLL_CTL_DEL,c.fd,nullptr);close(c.fd);refs.erase(c.id);clients.erase(it);}
static string reason(int n){switch(n){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 429:return "Too Many Requests";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";default:return "Error";}}
static void response(Conn &c,int status,uint64_t len,const string&extra=""){c.out="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(len)+"\r\nConnection: "+(c.closeafter?"close":"keep-alive")+"\r\n"+extra+"\r\n";c.sent=0;c.write=nowms();}
static void bad(Conn&c,int status){closeup(c);if(c.file>=0){close(c.file);c.file=-1;}c.active=true;c.closeafter=true;c.updone=true;response(c,status,0);}
static bool connectionclose(const string&s){size_t i=0;while(i<=s.size()){size_t j=s.find(',',i);if(j==string::npos)j=s.size();if(lower(trim(s.substr(i,j-i)))=="close")return true;if(j==s.size())break;i=j+1;}return false;}
struct Request{string method,target,host,real;bool http10=false,close=false,te=false,clseen=false;uint64_t cl=0;int hosts=0,reals=0;};
static bool parse(const string&h,Request&r){size_t e=h.find("\r\n");if(e==string::npos)return false;string line=h.substr(0,e);size_t a=line.find(' '),b=a==string::npos?a:line.find(' ',a+1);if(a==string::npos||b==string::npos||line.find(' ',b+1)!=string::npos||!a||b==a+1)return false;r.method=line.substr(0,a);for(unsigned char c:r.method)if(!tokenchar(c))return false;r.target=line.substr(a+1,b-a-1);for(unsigned char c:r.target)if(c<=32||c==127)return false;string v=line.substr(b+1);if(v!="HTTP/1.1"&&v!="HTTP/1.0")return false;r.http10=v=="HTTP/1.0";size_t i=e+2;while(i<h.size()){size_t j=h.find("\r\n",i);if(j==string::npos)return false;if(j==i)return j+2==h.size();string s=h.substr(i,j-i);if(s.empty()||s[0]==' '||s[0]=='\t')return false;size_t k=s.find(':');if(k==string::npos||k==0)return false;for(size_t q=0;q<k;q++)if(!tokenchar((unsigned char)s[q]))return false;for(size_t q=k+1;q<s.size();q++){unsigned char ch=s[q];if(ch==0||ch=='\r'||ch=='\n')return false;}string name=lower(s.substr(0,k)),val=trim(s.substr(k+1));if(name=="host"){r.hosts++;r.host=val;}else if(name=="connection"){if(connectionclose(val))r.close=true;}else if(name=="content-length"){if(r.clseen)return false;r.clseen=true;unsigned long long n;if(!number(val,n,false))return false;r.cl=n;}else if(name=="transfer-encoding")r.te=true;else if(name=="x-real-ip"){r.reals++;r.real=val;}i=j+2;}return false;}
static bool admit(uint32_t who,long long t){auto refill=[&](Bucket&x,uint64_t cap){x.tokens=min((double)cap,x.tokens+(double)(t-x.time)/(double)cfg.refill);x.time=t;};refill(globalbucket,cfg.gb);if(globalbucket.tokens<1)return false;auto it=buckets.find(who);if(it==buckets.end())it=buckets.emplace(who,Bucket{(double)cfg.cb,t}).first;auto &b=it->second;refill(b,cfg.cb);if(b.tokens<1)return false;b.tokens-=1;globalbucket.tokens-=1;return true;}
static void startup(Conn&c,const Request&r){int fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0){response(c,502,0);c.updone=true;return;}int rc=connect(fd,(sockaddr*)&cfg.up,sizeof cfg.up);if(rc<0&&errno!=EINPROGRESS){close(fd);response(c,502,0);c.updone=true;return;}c.ufd=fd;c.uid=nextid++;c.upconnecting=rc<0;c.upout=r.method+" "+r.target.substr(8)+" HTTP/1.1\r\nHost: "+r.host+"\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";c.upsent=0;c.upin.clear();c.upheader=false;c.upbuffer=false;c.updone=false;c.upactivity=nowms();refs[c.uid]={&c,true};if(!ctl(EPOLL_CTL_ADD,fd,EPOLLOUT|EPOLLRDHUP,c.uid)){refs.erase(c.uid);close(fd);c.ufd=-1;c.updone=true;response(c,502,0);}}
static void process(Conn&c){if(c.active)return;size_t p=c.in.find("\r\n\r\n");if(p==string::npos){if(c.in.size()>cfg.header)bad(c,431);else{for(size_t i=0;i<c.in.size();i++)if(c.in[i]==0||(c.in[i]=='\n'&&(i==0||c.in[i-1]!='\r'))||(c.in[i]=='\r'&&i+1<c.in.size()&&c.in[i+1]!='\n')){bad(c,400);break;}}return;}if(p+4>cfg.header){bad(c,431);return;}Request r;string h=c.in.substr(0,p+4);c.in.erase(0,p+4);c.first=c.in.empty()?0:c.lastread;c.active=true;c.updone=true;c.count++;c.closeafter=r.close;if(!parse(h,r)){bad(c,400);return;}c.closeafter=r.close||r.http10||c.count>=cfg.maxreq;c.head=r.method=="HEAD";string path;if(!pathdecode(r.target,path)){bad(c,400);return;}bool gateway=r.target.compare(0,9,"/gateway/")==0;if(!gateway&&traversal(path)){response(c,403,0);return;}if(r.te||r.clseen&&r.cl!=0){bad(c,400);return;}if(gateway&&(r.hosts!=1||r.host.empty())){bad(c,400);return;}if(r.method!="GET"&&r.method!="HEAD"){response(c,405,0);return;}if((r.method=="GET"||r.method=="HEAD")&&path=="/health"){response(c,200,3,"Content-Type: text/plain\r\n");if(!c.head)c.out+="ok\n";return;}if(gateway){uint32_t who=c.peer;if(c.peer==cfg.trust.s_addr&&r.reals==1){in_addr ip;if(inet_pton(AF_INET,r.real.c_str(),&ip)==1)who=ip.s_addr;}if(!admit(who,nowms())){response(c,429,0);return;}startup(c,r);return;}uint64_t size=0;int fd=fileopen(cfg.rootfd,path,size);if(fd<0){response(c,-fd,0);return;}response(c,200,size,"Content-Type: application/octet-stream\r\n");if(c.head)close(fd);else{c.file=fd;c.filerem=size;if(!size){close(fd);c.file=-1;}}}
static void upstream_fail(Conn&c){closeup(c);c.updone=true;if(!c.upheader||(c.upbuffer&&c.sent==0)){c.upheader=false;c.upbuffer=false;response(c,502,0);}else c.closeafter=true;}
static bool upstream_headers(Conn&c){size_t p=c.upin.find("\r\n\r\n");if(p==string::npos){if(c.upin.size()>65536)upstream_fail(c);return false;}string h=c.upin.substr(0,p+4);c.upin.erase(0,p+4);size_t e=h.find("\r\n");string line=h.substr(0,e);if(line.size()<12||line.compare(0,7,"HTTP/1.")||!(line[7]=='0'||line[7]=='1')||line[8]!=' '||!isdigit((unsigned char)line[9])||!isdigit((unsigned char)line[10])||!isdigit((unsigned char)line[11])){upstream_fail(c);return false;}int status=(line[9]-'0')*100+(line[10]-'0')*10+line[11]-'0';if(status<200||status>599){upstream_fail(c);return false;}bool has=false;uint64_t len=0;string extras;size_t i=e+2;while(i<p+2){size_t j=h.find("\r\n",i);if(j==string::npos||j==i){upstream_fail(c);return false;}string s=h.substr(i,j-i);size_t k=s.find(':');if(k==string::npos||k==0){upstream_fail(c);return false;}for(size_t q=0;q<k;q++)if(!tokenchar((unsigned char)s[q])){upstream_fail(c);return false;}string name=lower(s.substr(0,k)),v=trim(s.substr(k+1));for(unsigned char x:v)if(x==0||x=='\r'||x=='\n'||(x<32&&x!='\t')||x==127){upstream_fail(c);return false;}if(name=="content-length"){unsigned long long n;if(has||!number(v,n,false)){upstream_fail(c);return false;}has=true;len=n;}else if(name=="transfer-encoding"){upstream_fail(c);return false;}else if(name!="connection"&&name!="keep-alive"&&name!="proxy-connection"&&name!="upgrade"&&name!="trailer")extras+=s+"\r\n";i=j+2;}if(!has){upstream_fail(c);return false;}c.upheader=true;c.uprem=c.head?0:len;c.upbuffer=c.uprem<=131072;c.out="HTTP/1.1 "+to_string(status)+" "+(line.size()>13?line.substr(13):reason(status))+"\r\nContent-Length: "+to_string(len)+"\r\nConnection: "+(c.closeafter?"close":"keep-alive")+"\r\n"+extras+"\r\n";c.sent=0;c.write=nowms();return true;}
static void upstream_event(Conn&c,uint32_t ev){if(c.ufd<0)return;if(c.upconnecting&&(ev&(EPOLLOUT|EPOLLERR|EPOLLHUP))){int err=0;socklen_t n=sizeof err;if(getsockopt(c.ufd,SOL_SOCKET,SO_ERROR,&err,&n)||err){upstream_fail(c);return;}c.upconnecting=false;c.upactivity=nowms();}if(!c.upconnecting&&c.upsent<c.upout.size()&&(ev&EPOLLOUT)){ssize_t n=send(c.ufd,c.upout.data()+c.upsent,c.upout.size()-c.upsent,MSG_NOSIGNAL);if(n>0){c.upsent+=n;c.upactivity=nowms();}else if(n<0&&errno!=EAGAIN&&errno!=EWOULDBLOCK&&errno!=EINTR){upstream_fail(c);return;}}if(c.upsent==c.upout.size()&&(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP|EPOLLERR))){char buf[16384];while(c.ufd>=0&&(c.upbuffer||c.out.size()-c.sent<131072)){ssize_t n=recv(c.ufd,buf,sizeof buf,0);if(n>0){c.upactivity=nowms();if(!c.upheader){c.upin.append(buf,n);if(!upstream_headers(c)){if(c.ufd<0)return;continue;}if(c.uprem){size_t take=min<uint64_t>(c.uprem,c.upin.size());c.out.append(c.upin.data(),take);c.uprem-=take;}c.upin.clear();}else{size_t take=min<uint64_t>(c.uprem,n);c.out.append(buf,take);c.uprem-=take;}if(c.upheader&&c.uprem==0){closeup(c);c.updone=true;c.write=nowms();return;}}else if(n==0){if(!c.upheader||c.uprem)upstream_fail(c);else{closeup(c);c.updone=true;}return;}else{if(errno==EINTR)continue;if(errno!=EAGAIN&&errno!=EWOULDBLOCK)upstream_fail(c);return;}}}}
static bool drive(Conn&c){if(!c.active)process(c);if(c.active&&c.sent<c.out.size()&&(!c.upbuffer||c.updone)){while(c.sent<c.out.size()){ssize_t n=send(c.fd,c.out.data()+c.sent,c.out.size()-c.sent,MSG_NOSIGNAL);if(n>0){c.sent+=n;c.write=nowms();c.last=c.write;}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else return false;}}if(c.sent==c.out.size()&&c.sent){c.out.clear();c.sent=0;}else if(c.sent>=65536){c.out.erase(0,c.sent);c.sent=0;}if(c.active&&c.out.empty()&&c.file>=0){while(c.filerem){ssize_t n=sendfile(c.fd,c.file,nullptr,min<uint64_t>(c.filerem,1<<20));if(n>0){c.filerem-=n;c.write=nowms();c.last=c.write;}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else return false;}if(!c.filerem){close(c.file);c.file=-1;}}if(c.active&&c.out.empty()&&c.file<0&&c.updone){if(c.closeafter)return false;c.active=false;c.last=nowms();if(!c.in.empty())return drive(c);if(c.rdhup)return false;}uint32_t ce=0;if(!c.active&&!c.rdhup&&c.in.size()<=cfg.header)ce|=EPOLLIN;if(c.active&&((!c.out.empty()&&(!c.upbuffer||c.updone))||c.file>=0))ce|=EPOLLOUT;ctl(EPOLL_CTL_MOD,c.fd,ce,c.id);if(c.ufd>=0){uint32_t ue=EPOLLRDHUP;if(c.upconnecting||c.upsent<c.upout.size())ue|=EPOLLOUT;else if(c.upbuffer||c.out.size()-c.sent<131072)ue|=EPOLLIN;ctl(EPOLL_CTL_MOD,c.ufd,ue,c.uid);}return true;}
static bool client_event(Conn&c,uint32_t ev){if(ev&EPOLLIN){char b[16384];while(!c.active){ssize_t n=recv(c.fd,b,sizeof b,0);if(n>0){long long t=nowms();if(c.in.empty())c.first=t;c.last=t;c.lastread=t;c.in.append(b,n);process(c);if(c.active)break;}else if(n==0){c.rdhup=true;break;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else return false;}}if(ev&EPOLLERR)return false;return drive(c);}
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;configpath=argv[2];if(!loadconfig(configpath,cfg))return 1;signal(SIGPIPE,SIG_IGN);struct sigaction sa{};sa.sa_handler=onhup;sigemptyset(&sa.sa_mask);sigaction(SIGHUP,&sa,nullptr);lfd=listener(cfg.bindaddr);if(lfd<0)return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0||!ctl(EPOLL_CTL_ADD,lfd,EPOLLIN,1))return 1;globalbucket={(double)cfg.gb,nowms()};epoll_event events[512];while(true){if(reload_flag){reload_flag=0;Config n;if(loadconfig(configpath,n)){int nl=lfd;if(n.listen!=cfg.listen)nl=listener(n.bindaddr);if(nl>=0){if(nl!=lfd){ctl(EPOLL_CTL_ADD,nl,EPOLLIN,1);epoll_ctl(ep,EPOLL_CTL_DEL,lfd,nullptr);close(lfd);lfd=nl;}close(cfg.rootfd);cfg=n;buckets.clear();globalbucket={(double)cfg.gb,nowms()};}else close(n.rootfd);}}int n=epoll_wait(ep,events,512,100);if(n<0){if(errno==EINTR)continue;break;}for(int i=0;i<n;i++){uint64_t id=events[i].data.u64;if(id==1){while(true){sockaddr_in peer{};socklen_t z=sizeof peer;int fd=accept4(lfd,(sockaddr*)&peer,&z,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR)continue;break;}if(clients.size()>=cfg.maxconn){close(fd);continue;}int one=1;setsockopt(fd,IPPROTO_TCP,TCP_NODELAY,&one,sizeof one);auto c=make_unique<Conn>();c->fd=fd;c->id=nextid++;c->peer=peer.sin_addr.s_addr;c->last=nowms();uint64_t cid=c->id;refs[cid]={c.get(),false};clients[cid]=move(c);if(!ctl(EPOLL_CTL_ADD,fd,EPOLLIN|EPOLLRDHUP,cid))destroy(cid);}continue;}auto it=refs.find(id);if(it==refs.end())continue;Conn*c=it->second.c;uint64_t cid=c->id;bool ok=true;if(it->second.upstream){upstream_event(*c,events[i].events);ok=drive(*c);}else ok=client_event(*c,events[i].events);if(!ok)destroy(cid);}long long t=nowms();vector<uint64_t> dead;for(auto &it:clients){Conn &c=*it.second;if(!c.active){if(c.first&&t-c.first>=(long long)cfg.htime)dead.push_back(c.id);else if(!c.first&&t-c.last>=(long long)cfg.idle)dead.push_back(c.id);}else{if(c.ufd>=0&&t-c.upactivity>=(long long)cfg.wtime){upstream_fail(c);if(!drive(c)){dead.push_back(c.id);continue;}}if(((!c.out.empty()&&(!c.upbuffer||c.updone))||c.file>=0)&&t-c.write>=(long long)cfg.wtime)dead.push_back(c.id);}}for(auto id:dead)destroy(id);}return 0;}
